CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('master','admin','viewer') NOT NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE invitations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, token_hash CHAR(64) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, role ENUM('admin','viewer') NOT NULL, created_by INT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, accepted_at DATETIME NULL, accepted_user_id INT UNSIGNED NULL, cancelled_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_invitations_creator FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_invitations_user FOREIGN KEY(accepted_user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE login_attempts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, ip VARCHAR(45) NOT NULL, username VARCHAR(60) NOT NULL DEFAULT '', kind ENUM('login','invite') NOT NULL, success TINYINT(1) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_login_attempts_window(ip,kind,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE students (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, belt ENUM('white','orange','green','blue','purple','brown','black') NOT NULL, degrees TINYINT UNSIGNED NOT NULL DEFAULT 0, last_graduation_at DATE NULL, active TINYINT(1) NOT NULL DEFAULT 1, created_by INT UNSIGNED NULL, updated_by INT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_students_created FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_students_updated FOREIGN KEY(updated_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE events (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(150) NOT NULL, event_date DATE NOT NULL, created_by INT UNSIGNED NULL, updated_by INT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_events_created FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_events_updated FOREIGN KEY(updated_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE graduations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, student_id INT UNSIGNED NOT NULL, event_id INT UNSIGNED NULL, from_belt ENUM('white','orange','green','blue','purple','brown','black') NOT NULL, from_degrees TINYINT UNSIGNED NOT NULL, to_belt ENUM('white','orange','green','blue','purple','brown','black') NOT NULL, to_degrees TINYINT UNSIGNED NOT NULL, status ENUM('planned','done') NOT NULL, hidden TINYINT(1) NOT NULL DEFAULT 0, graduated_at DATE NULL, graduated_by INT UNSIGNED NULL, created_by INT UNSIGNED NULL, updated_by INT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_graduations_student FOREIGN KEY(student_id) REFERENCES students(id), CONSTRAINT fk_graduations_event FOREIGN KEY(event_id) REFERENCES events(id), CONSTRAINT fk_graduations_graduated_by FOREIGN KEY(graduated_by) REFERENCES users(id), CONSTRAINT fk_graduations_created FOREIGN KEY(created_by) REFERENCES users(id), CONSTRAINT fk_graduations_updated FOREIGN KEY(updated_by) REFERENCES users(id), UNIQUE KEY uq_graduations_event_student(event_id,student_id), INDEX idx_graduations_student_status(student_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
